//! The fixture corpus (PLAN.md §5).
//!
//! Layout under `fixtures/`:
//!
//! | Directory | Kind | Committed |
//! |---|---|---|
//! | `<format>/features/` | [`FixtureKind::Features`]: generated by `tools/make-fixtures.py` | yes |
//! | `<format>/manual/` | [`FixtureKind::Manual`]: hand-made edge cases | yes |
//! | `<format>/large/`, `large/` | [`FixtureKind::Large`]: generated on demand (`--large`, `--synthetic-large`) | no |
//! | `external/<format>/` | [`FixtureKind::External`]: real-world files from `tools/fetch-corpus.sh` | no |
//! | `<format>/charts/` | [`FixtureKind::Charts`]: one workbook per chart type (`generate.py`) | yes |
//!
//! `<format>` is `docx`, `xlsx` or `pptx`. Files are discovered by extension, so READMEs,
//! generators and oracle JSON next to them are ignored.

pub mod corpus;

use std::fmt;
use std::path::{Path, PathBuf};

pub use corpus::{Corpus, CorpusChecks, CorpusEntry};

/// An Office file format of the corpus.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum FixtureFormat {
    /// WordprocessingML (`.docx`).
    Docx,
    /// SpreadsheetML (`.xlsx`).
    Xlsx,
    /// PresentationML (`.pptx`).
    Pptx,
}

impl FixtureFormat {
    /// Every format, in report order.
    pub const ALL: [FixtureFormat; 3] = [Self::Docx, Self::Xlsx, Self::Pptx];

    /// The file extension (and directory name), without the dot.
    #[must_use]
    pub const fn extension(self) -> &'static str {
        match self {
            Self::Docx => "docx",
            Self::Xlsx => "xlsx",
            Self::Pptx => "pptx",
        }
    }

    /// Parses `docx`, `xlsx` or `pptx` (any case, with or without a leading dot).
    #[must_use]
    pub fn parse(name: &str) -> Option<Self> {
        let n = name.trim_start_matches('.').to_ascii_lowercase();
        Self::ALL.into_iter().find(|f| f.extension() == n)
    }

    /// The format of a path, from its extension.
    #[must_use]
    pub fn from_path(path: &Path) -> Option<Self> {
        path.extension()
            .and_then(|e| e.to_str())
            .and_then(Self::parse)
    }
}

impl fmt::Display for FixtureFormat {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.extension())
    }
}

/// Where a fixture comes from.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum FixtureKind {
    /// Generated feature files (`<format>/features/`).
    Features,
    /// Hand-made edge cases (`<format>/manual/`).
    Manual,
    /// Large generated files (`<format>/large/`, `large/`), not committed.
    Large,
    /// Downloaded real-world files (`external/<format>/`), not committed.
    External,
    /// One workbook per chart type (`<format>/charts/`, generated by its `generate.py`).
    Charts,
}

impl FixtureKind {
    /// Every kind, in discovery order.
    pub const ALL: [FixtureKind; 5] = [
        Self::Features,
        Self::Manual,
        Self::Charts,
        Self::Large,
        Self::External,
    ];

    /// The kind's name as used in directory names and reports.
    #[must_use]
    pub const fn name(self) -> &'static str {
        match self {
            Self::Features => "features",
            Self::Manual => "manual",
            Self::Large => "large",
            Self::External => "external",
            Self::Charts => "charts",
        }
    }
}

impl fmt::Display for FixtureKind {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.name())
    }
}

/// One fixture file.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct Fixture {
    /// Path relative to the fixtures root, with `/` separators (`docx/features/tables.docx`), as
    /// `parity/corpus.json` names it.
    pub rel: String,
    /// Absolute (or root-joined) path.
    pub path: PathBuf,
    /// Its format.
    pub format: FixtureFormat,
    /// Its kind.
    pub kind: FixtureKind,
}

impl Fixture {
    /// Reads the file.
    ///
    /// # Errors
    ///
    /// The I/O error, with the path in the message.
    pub fn read(&self) -> Result<Vec<u8>, String> {
        std::fs::read(&self.path).map_err(|e| format!("{}: {e}", self.path.display()))
    }

    /// The file name (`tables.docx`).
    #[must_use]
    pub fn file_name(&self) -> &str {
        self.rel.rsplit('/').next().unwrap_or(&self.rel)
    }
}

/// The fixtures root of the repository (`<repo>/fixtures`).
#[must_use]
pub fn fixtures_dir() -> PathBuf {
    crate::repo_root().join("fixtures")
}

/// The directory holding fixtures of one format and kind, relative to the fixtures root.
#[must_use]
pub fn kind_dir(format: FixtureFormat, kind: FixtureKind) -> String {
    match kind {
        FixtureKind::External => format!("external/{format}"),
        _ => format!("{format}/{kind}"),
    }
}

fn files_in(root: &Path, rel_dir: &str, format: FixtureFormat, kind: FixtureKind) -> Vec<Fixture> {
    let Ok(entries) = std::fs::read_dir(root.join(rel_dir)) else {
        return Vec::new();
    };
    let mut out: Vec<Fixture> = entries
        .filter_map(Result::ok)
        .filter(|e| e.file_type().is_ok_and(|t| t.is_file()))
        .filter_map(|e| {
            let name = e.file_name().to_str()?.to_owned();
            (FixtureFormat::parse(name.rsplit('.').next()?)? == format).then(|| Fixture {
                rel: format!("{rel_dir}/{name}"),
                path: e.path(),
                format,
                kind,
            })
        })
        .collect();
    out.sort();
    out
}

/// The fixtures of one format and kind under `root`, sorted by path. Missing directories give an
/// empty list (external and large fixtures are optional).
#[must_use]
pub fn list_in(root: &Path, format: FixtureFormat, kind: FixtureKind) -> Vec<Fixture> {
    let mut out = files_in(root, &kind_dir(format, kind), format, kind);
    if kind == FixtureKind::Large {
        // `fixtures/large/` holds the synthetic files of every format (`--synthetic-large`).
        out.extend(files_in(root, "large", format, kind));
        out.sort();
    }
    out
}

/// Every fixture under `root` of the given formats and kinds, in format, kind and name order.
#[must_use]
pub fn discover_in(root: &Path, formats: &[FixtureFormat], kinds: &[FixtureKind]) -> Vec<Fixture> {
    let mut out = Vec::new();
    for &format in formats {
        for &kind in kinds {
            out.extend(list_in(root, format, kind));
        }
    }
    out
}

/// Every fixture of the repository's corpus (all formats and kinds that exist).
#[must_use]
pub fn discover() -> Vec<Fixture> {
    discover_in(&fixtures_dir(), &FixtureFormat::ALL, &FixtureKind::ALL)
}

/// Resolves a fixture name: a path relative to the fixtures root (`docx/features/tables.docx`)
/// or a bare file name (`tables.docx`), looked up in `features/`, `manual/`, `large/` and
/// `external/` of the format given by its extension.
///
/// # Errors
///
/// A message listing where it looked.
pub fn find(name: &str) -> Result<Fixture, String> {
    find_in(&fixtures_dir(), name)
}

/// [`find`] under another fixtures root.
///
/// # Errors
///
/// A message listing where it looked.
pub fn find_in(root: &Path, name: &str) -> Result<Fixture, String> {
    let format = FixtureFormat::from_path(Path::new(name))
        .ok_or_else(|| format!("{name}: not a .docx, .xlsx or .pptx fixture"))?;
    if name.contains('/') {
        let rel = name.trim_start_matches("fixtures/");
        let path = root.join(rel);
        if !path.is_file() {
            return Err(format!("no fixture {rel} under {}", root.display()));
        }
        let kind = FixtureKind::ALL
            .into_iter()
            .find(|k| rel.split('/').any(|seg| seg == k.name()))
            .unwrap_or(FixtureKind::Manual);
        return Ok(Fixture {
            rel: rel.to_owned(),
            path,
            format,
            kind,
        });
    }
    let mut looked = Vec::new();
    for kind in FixtureKind::ALL {
        let dir = kind_dir(format, kind);
        let path = root.join(&dir).join(name);
        if path.is_file() {
            return Ok(Fixture {
                rel: format!("{dir}/{name}"),
                path,
                format,
                kind,
            });
        }
        looked.push(dir);
    }
    Err(format!(
        "no fixture named {name} (looked in {} under {})",
        looked.join(", "),
        root.display()
    ))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn formats_parse_from_names_and_paths() {
        assert_eq!(FixtureFormat::parse(".DOCX"), Some(FixtureFormat::Docx));
        assert_eq!(FixtureFormat::parse("odt"), None);
        assert_eq!(
            FixtureFormat::from_path(Path::new("a/b.pptx")),
            Some(FixtureFormat::Pptx)
        );
        assert_eq!(FixtureFormat::from_path(Path::new("README")), None);
        assert_eq!(
            kind_dir(FixtureFormat::Xlsx, FixtureKind::External),
            "external/xlsx"
        );
        assert_eq!(
            kind_dir(FixtureFormat::Xlsx, FixtureKind::Features),
            "xlsx/features"
        );
    }

    #[test]
    fn discovers_the_committed_feature_corpus() {
        let all = discover();
        for format in FixtureFormat::ALL {
            let n = all
                .iter()
                .filter(|f| f.format == format && f.kind == FixtureKind::Features)
                .count();
            assert!(n >= 19, "{format}: only {n} feature fixtures");
        }
        assert!(all.iter().all(|f| f.path.is_file()));
        assert!(
            all.iter()
                .all(|f| f.rel.ends_with(&format!(".{}", f.format)))
        );
        // Sorted, no duplicates.
        let mut sorted = all.clone();
        sorted.sort_by(|a, b| (a.format, a.kind, &a.rel).cmp(&(b.format, b.kind, &b.rel)));
        sorted.dedup();
        assert_eq!(sorted.len(), all.len());
    }

    #[test]
    fn finds_fixtures_by_name_and_path() {
        let f = find("tables.docx").unwrap();
        assert_eq!(f.rel, "docx/features/tables.docx");
        assert_eq!(f.kind, FixtureKind::Features);
        assert_eq!(f.file_name(), "tables.docx");
        let m = find("minimal.docx").unwrap();
        assert_eq!(m.kind, FixtureKind::Manual);
        let p = find("fixtures/xlsx/features/styles.xlsx").unwrap();
        assert_eq!(p.rel, "xlsx/features/styles.xlsx");
        assert!(find("nope.docx").unwrap_err().contains("looked in"));
        assert!(find("notes.txt").is_err());
        assert!(!f.read().unwrap().is_empty());
    }
}
